NSPoint : struct {
    x : CGFloat = 0.0
    y : CGFloat = 0.0
}

NSSize : struct {
    width : CGFloat = 0.0
    height : CGFloat = 0.0
}

NSRect : struct {
    origin : NSPoint = NSPoint {}
    size : NSSize = NSSize {}
}

NSWindowResizeContext : struct {
    callback : NSWindowResizeCallback
    user_data : ^void = null
}

NSWindowResizeObserver : struct {
    handle : core.ObjCId = null
    // init owns this malloc-backed callback context; deinit clears and frees it.
    context : ^NSWindowResizeContext = null
}

NSRange : struct {
    location : macos_core.NSUInteger = 0
    length : macos_core.NSUInteger = 0
}

CFRange : struct {
    location : CFIndex = 0
    length : CFIndex = 0
}

MTLClearColor : struct {
    red : f64 = 0.0
