    blue : f64 = 0.0
    alpha : f64 = 1.0
}

MTLOrigin : struct {
    x : core.NSUInteger = 0
    y : core.NSUInteger = 0
    z : core.NSUInteger = 0
}

MTLSize : struct {
    width : core.NSUInteger = 0
    height : core.NSUInteger = 0
    depth : core.NSUInteger = 0
}

MTLRegion : struct {
    origin : MTLOrigin {}
    size : MTLSize {}
}

MTLScissorRect : struct {
    x : core.NSUInteger = 0
    y : core.NSUInteger = 0
    width : core.NSUInteger = 0
    height : core.NSUInteger = 0
}

MTKViewDelegateContext : struct {
    draw_callback : MTKViewDrawCallback
    drawable_size_will_change_callback : MTKViewDrawableSizeWillChangeCallback
    user_data : ^void = null
}

MTKViewDelegate : struct {
    handle : core.ObjCId = null
    // create_MTKViewDelegate owns this malloc-backed callback context.
    context : ^MTKViewDelegateContext = null
}

ViewportUniforms : struct {
